4511	private func makeSpeedTrackSegments(from points: [TrackSpeedPoint]) -> [TrackSpeedSegment] {
4512	    guard points.count > 1 else { return [] }
4513	
4514	    return (0..<(points.count - 1)).map { index in
4515	        let start = points[index]
4516	        let end = points[index + 1]
4517	        let speed = end.speedKmh ?? start.speedKmh
4518	        return TrackSpeedSegment(
4519	            id: "\(start.id)-\(end.id)-\(index)",
4520	            coordinates: [start.coordinate, end.coordinate],
4521	            speedKmh: speed
4522	        )
4523	    }
4524	}
