798	                center: CLLocationCoordinate2D(latitude: 31.2304, longitude: 121.4737),
799	                span: MKCoordinateSpan(latitudeDelta: 0.03, longitudeDelta: 0.03)
800	            )
801	        }
802	
803	        let minLatitude = coordinates.map(\.latitude).min() ?? coordinates[0].latitude
804	        let maxLatitude = coordinates.map(\.latitude).max() ?? coordinates[0].latitude
805	        let minLongitude = coordinates.map(\.longitude).min() ?? coordinates[0].longitude
806	        let maxLongitude = coordinates.map(\.longitude).max() ?? coordinates[0].longitude
807	        let center = CLLocationCoordinate2D(
808	            latitude: (minLatitude + maxLatitude) / 2,
809	            longitude: (minLongitude + maxLongitude) / 2
810	        )
811	        return MKCoordinateRegion(
812	            center: center,
813	            span: MKCoordinateSpan(
814	                latitudeDelta: max((maxLatitude - minLatitude) * 1.5, 0.006),
815	                longitudeDelta: max((maxLongitude - minLongitude) * 1.5, 0.006)
816	            )
817	        )
