1048	private func formatRecordingDuration(_ seconds: TimeInterval) -> String {
1049	    let seconds = max(Int(seconds), 0)
1050	    let hours = seconds / 3600
1051	    let minutes = (seconds % 3600) / 60
1052	    let restSeconds = seconds % 60
1053	    if hours > 0 {
1054	        return String(format: "%d:%02d:%02d", hours, minutes, restSeconds)
1055	    }
1056	    return String(format: "%02d:%02d", minutes, restSeconds)
1057	}
