1066	private func formatRecordingNumber(
1067	    _ value: Double,
1068	    unit: String,
1069	    maximumFractionDigits: Int,
1070	    minimumFractionDigits: Int = 0
1071	) -> String {
1072	    let formatter = NumberFormatter()
1073	    formatter.maximumFractionDigits = maximumFractionDigits
1074	    formatter.minimumFractionDigits = minimumFractionDigits
1075	    let text = formatter.string(from: NSNumber(value: value)) ?? "\(value)"
1076	    return "\(text)\(unit)"
