16	func tripMonthString(for date: Date) -> String {
17	    let formatter = DateFormatter()
18	    formatter.calendar = Calendar(identifier: .gregorian)
19	    formatter.locale = Locale(identifier: "en_US_POSIX")
20	    formatter.timeZone = TimeZone(identifier: "Asia/Shanghai") ?? .current
21	    formatter.dateFormat = "yyyyMM"
22	    return formatter.string(from: date)
23	}
