25	func previousTripMonth(before month: String) -> String {
26	    guard month.count == 6,
27	          let year = Int(month.prefix(4)),
28	          let monthValue = Int(month.suffix(2)) else {
29	        return tripMonthString(for: Date())
30	    }
31	    var calendar = Calendar(identifier: .gregorian)
32	    calendar.timeZone = TimeZone(identifier: "Asia/Shanghai") ?? .current
33	    let date = calendar.date(from: DateComponents(year: year, month: monthValue, day: 1)) ?? Date()
34	    let previous = calendar.date(byAdding: .month, value: -1, to: date) ?? date
35	    return tripMonthString(for: previous)
36	}
